   184→			<Button
   185→				variant="ghost"
   186→				size="icon-sm"
   187→				class="bg-accent"
   188→				title="Board view"
   189→				aria-pressed="true"
   190→			>
   191→				<LayoutGrid class="size-4" />
   192→			</Button>
   193→			<a href="{base}/tasks" title="List view">
   194→				<Button variant="ghost" size="icon-sm" aria-pressed="false">
   195→					<List class="size-4" />
   196→				</Button>
   197→			</a>
   198→		</div>
   199→	</div>
   200→
   201→	<!-- Error -->
   202→	{#if error}
   203→		<div class="mx-6 mt-4 bg-destructive/10 text-destructive p-4 rounded-lg" role="alert" data-testid="board-error">
   204→			{error}
   205→		</div>
